import{_ as t,c as e,o as a,a2 as o}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Notifications","description":"","frontmatter":{"sidebarPos":15,"sidebarTitle":"Overview","sidebarGroupTitle":"Notifications"},"headers":[],"relativePath":"system-reference/backend/notifications/overview.md","filePath":"system-reference/backend/notifications/overview.md","lastUpdated":1778363927000}'),i={name:"system-reference/backend/notifications/overview.md"},n=o(`<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><p>Modularous ships two tiers of notifications that serve different purposes.</p><table><thead><tr><th>Tier</th><th>Namespace</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Auth notifications</strong></td><td><code>Unusualify\\Modularous\\Notifications\\</code></td><td>Low-level transactional emails for registration and password flows</td></tr><tr><td><strong>System notifications</strong></td><td><code>Modules\\SystemNotification\\Notifications\\</code></td><td>Feature-rich, queue-able, multi-channel notifications tied to model lifecycle events</td></tr></tbody></table><hr><h2 id="tier-1-—-auth-notifications" tabindex="-1">Tier 1 — Auth Notifications <a class="header-anchor" href="#tier-1-—-auth-notifications" aria-label="Permalink to &quot;Tier 1 — Auth Notifications&quot;">​</a></h2><p>Three standalone notification classes in <code>src/Notifications/</code>:</p><table><thead><tr><th>Class</th><th>Triggered by</th><th>Email subject</th></tr></thead><tbody><tr><td><a href="./auth-notifications#emailverification">EmailVerification</a></td><td>Registration with email verification</td><td>&quot;Email Verification&quot;</td></tr><tr><td><a href="./auth-notifications#generatepasswordnotification">GeneratePasswordNotification</a></td><td>New account with generated password</td><td>&quot;Generate Your Password For New Account&quot;</td></tr><tr><td><a href="./auth-notifications#resetpasswordnotification">ResetPasswordNotification</a></td><td>Forgot-password flow</td><td>&quot;Reset your {app} password&quot;</td></tr></tbody></table><p>These extend Laravel&#39;s <code>Notification</code> directly, deliver only via <code>mail</code>, and are <strong>not queued</strong> by default.</p><p>→ <a href="./auth-notifications">Auth Notifications reference</a></p><hr><h2 id="tier-2-—-system-notifications" tabindex="-1">Tier 2 — System Notifications <a class="header-anchor" href="#tier-2-—-system-notifications" aria-label="Permalink to &quot;Tier 2 — System Notifications&quot;">​</a></h2><p>Fourteen notification classes in the <code>SystemNotification</code> module, all extending <code>FeatureNotification</code>:</p><table><thead><tr><th>Class</th><th>Triggered by</th><th>Default channels</th></tr></thead><tbody><tr><td><a href="./system-notifications#model-lifecycle">ModelCreatedNotification</a></td><td><code>ModelCreated</code> event</td><td><code>mail</code></td></tr><tr><td><a href="./system-notifications#model-lifecycle">ModelUpdatedNotification</a></td><td><code>ModelUpdated</code> event</td><td><code>mail</code></td></tr><tr><td><a href="./system-notifications#model-lifecycle">ModelDeletedNotification</a></td><td><code>ModelDeleted</code> event</td><td><code>mail</code></td></tr><tr><td><a href="./system-notifications#model-lifecycle">ModelRestoredNotification</a></td><td><code>ModelRestored</code> event</td><td><code>mail</code></td></tr><tr><td><a href="./system-notifications#model-lifecycle">ModelForceDeletedNotification</a></td><td><code>ModelForceDeleted</code> event</td><td><code>mail</code></td></tr><tr><td><a href="./system-notifications#stateable">StateableUpdatedNotification</a></td><td><code>StateableUpdated</code> event</td><td>configurable</td></tr><tr><td><a href="./system-notifications#tasks">TaskCreatedNotification</a></td><td><code>AssignmentCreated</code> event</td><td>configurable</td></tr><tr><td><a href="./system-notifications#tasks">TaskUpdatedNotification</a></td><td><code>AssignmentUpdated</code> event</td><td>configurable</td></tr><tr><td><a href="./system-notifications#tasks">TaskAssignedToAuthorizableNotification</a></td><td><code>AssignmentCreated</code> event</td><td><code>database,mail</code></td></tr><tr><td><a href="./system-notifications#payment">PaymentCompletedNotification</a></td><td><code>PaymentCompleted</code> event</td><td>configurable</td></tr><tr><td><a href="./system-notifications#payment">PaymentFailedNotification</a></td><td><code>PaymentFailed</code> event</td><td><code>database,mail</code></td></tr><tr><td><a href="./system-notifications#chat">ChatableUnreadNotification</a></td><td><code>UnreadChatMessage</code> event</td><td>configurable</td></tr><tr><td><a href="./feature-notification">FeatureNotification</a></td><td>Abstract base — not dispatched directly</td><td>—</td></tr><tr><td><a href="./system-notifications#log">LogNotification</a></td><td>Monolog handler</td><td><code>mail</code></td></tr></tbody></table><p>→ <a href="./feature-notification">FeatureNotification base class</a><br> → <a href="./system-notifications">System Notifications reference</a></p><hr><h2 id="notification-model" tabindex="-1">Notification Model <a class="header-anchor" href="#notification-model" aria-label="Permalink to &quot;Notification Model&quot;">​</a></h2><p>The <code>SystemNotification</code> module stores database-channel notifications in a <code>notifications</code> table via the <code>Notification</code> Eloquent model.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>notifications table</span></span>
<span class="line"><span>├── id            (UUID string, non-incrementing)</span></span>
<span class="line"><span>├── type          (fully-qualified notification class name)</span></span>
<span class="line"><span>├── notifiable_type / notifiable_id  (polymorphic)</span></span>
<span class="line"><span>├── data          (JSON — subject, message, htmlMessage, redirector, …)</span></span>
<span class="line"><span>└── read_at       (nullable datetime)</span></span></code></pre></div><p>Appended attributes on the model: <code>is_read</code>, <code>is_mine</code>, <code>subject</code>, <code>message</code>, <code>html_message</code>, <code>redirector</code>, <code>has_redirector</code>, <code>redirector_text</code>.</p><hr><h2 id="flow-event-→-listener-→-notification" tabindex="-1">Flow: Event → Listener → Notification <a class="header-anchor" href="#flow-event-→-listener-→-notification" aria-label="Permalink to &quot;Flow: Event → Listener → Notification&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Model saved / state changed / payment event]</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  SystemNotification Event dispatched</span></span>
<span class="line"><span>  (e.g. ModelUpdated, StateableUpdated)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  Listener::handle($event)</span></span>
<span class="line"><span>  (e.g. ModelListener, StateableListener)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► notification-&gt;notify(...)  [database channel]</span></span>
<span class="line"><span>        │       stored in notifications table</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └─► Notification::route(&#39;mail&#39;, ...)  [mail channel]</span></span>
<span class="line"><span>                queued via modularous.notifications.mail_queue</span></span></code></pre></div><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>All system-notification behaviour is governed by <code>config/modularous.php</code> under the <code>notifications</code> key:</p><table><thead><tr><th>Key</th><th>Description</th></tr></thead><tbody><tr><td><code>modularous.mail.enabled</code></td><td>Master switch — disables all mail from <code>Listener::handle()</code> when <code>false</code></td></tr><tr><td><code>modularous.notifications.mail_connection</code></td><td>Queue connection used for mail channel</td></tr><tr><td><code>modularous.notifications.database_connection</code></td><td>Queue connection used for database channel</td></tr><tr><td><code>modularous.notifications.mail_queue</code></td><td>Queue name for mail jobs</td></tr><tr><td><code>modularous.notifications.database_queue</code></td><td>Queue name for database notification jobs</td></tr><tr><td><code>modularous.notifications.{ClassName}.channels</code></td><td>Per-class channel override (comma-separated string)</td></tr><tr><td><code>modularous.notifications.authorizable.channels</code></td><td>Channel override for <code>TaskAssignedToAuthorizableNotification</code></td></tr></tbody></table>`,26),d=[n];function s(c,r,l,f,p,h){return a(),e("div",null,d)}const b=t(i,[["render",s]]);export{m as __pageData,b as default};
